begin;

create temporary table desired_printer_content (
  model text primary key,
  description text not null,
  page_content jsonb not null
) on commit drop;

insert into desired_printer_content (model, description, page_content)
values
    ('L15180', 'طابعة EcoTank احترافية للأعمال تدعم A3+ مع طباعة ومسح ونسخ وفاكس، اتصال شبكي متكامل وطباعة مزدوجة تلقائية.', '{"detailedDescription":"تجمع Epson EcoTank L15180 بين الطباعة والنسخ والمسح الضوئي والفاكس في جهاز أعمال ملون يدعم الطباعة حتى مقاس A3+. وتستخدم رأس PrecisionCore بسرعة تصل إلى 25 صورة في الدقيقة، ما يجعلها ملائمة للفرق التي تنجز التقارير والجداول والمستندات الكبيرة بصورة متكررة.\n\nتضم وحدة ADF بسعة 50 ورقة، وتوفر الطباعة التلقائية على الوجهين حتى مقاس A3. كما تدعم Wi-Fi وWi-Fi Direct وEthernet وUSB والطباعة من الجوال، لتعمل كجهاز مشترك يمكن الوصول إليه من الحواسيب والأجهزة المحمولة داخل المكتب.\n\nتناسب L15180 الشركات ومجموعات العمل ذات أحجام الطباعة المرتفعة التي تحتاج إلى مرونة A3+ دون التخلي عن اقتصاد خزانات EcoTank. وتميزها العملي عن الطابعات المكتبية الأبسط هو الجمع بين المقاس الكبير، والسرعة، والفاكس، والتغذية التلقائية للمستندات، والاتصال الشبكي في جهاز واحد.","productFeatures":[{"title":"طباعة مكتبية حتى A3+","description":"تطبع المستندات والجداول والمواد الملونة حتى مقاس A3+، فتمنح فرق العمل مساحة أكبر من A4 عند إعداد الملفات واسعة التنسيق."},{"title":"أداء يصل إلى 25 صورة في الدقيقة","description":"تساعد سرعة الطباعة على إنجاز دفعات التقارير والمراسلات بوتيرة مناسبة للعمل المكتبي النشط، بدل الانتظار الطويل بين المهام المتتابعة."},{"title":"وظائف متكاملة مع ADF","description":"تجمع الطباعة والنسخ والمسح والفاكس، وتستوعب وحدة ADF حتى 50 ورقة لمعالجة الملفات متعددة الصفحات بخطوات يدوية أقل."},{"title":"طباعة تلقائية على الوجهين حتى A3","description":"تُخرج المستندات المزدوجة تلقائيًا حتى مقاس A3، ما يسهّل إعداد التقارير الكبيرة ويقلل الحاجة إلى قلب الأوراق يدويًا."},{"title":"اتصال شبكي ولاسلكي مرن","description":"تدعم Ethernet وWi-Fi وWi-Fi Direct وUSB والطباعة من الجوال، لتناسب المشاركة بين عدة مستخدمين وطرق اتصال مختلفة."},{"title":"أحبار Pigment موجهة للأعمال","description":"تعتمد أربعة ألوان DURABrite ET Pigment لإنتاج نصوص ورسومات مكتبية واضحة، مع نظام خزانات يخفف تكرار استبدال مستلزمات الحبر."}],"productUses":[{"title":"إعداد التقارير والجداول واسعة التنسيق","description":"تفيد الأقسام التي تطبع جداول البيانات والمخططات والتقارير التي تستفيد من مساحة A3 أو A3+ لعرض التفاصيل بوضوح."},{"title":"إدارة المستندات اليومية للشركات","description":"تجمع الطباعة والنسخ والمسح والفاكس لتغطية دورة المستند المكتبي من جهاز واحد مشترك."},{"title":"معالجة الملفات متعددة الصفحات","description":"تساعد وحدة ADF بسعة 50 ورقة في نسخ المستندات أو مسحها أو إرسالها بالفاكس دون إدخال كل صفحة على حدة."},{"title":"الطباعة المتكررة لمجموعات العمل","description":"تلائم الفرق التي تنجز كميات مرتفعة من المستندات وتحتاج إلى سرعة عملية وخزانات حبر تقلل المقاطعات."},{"title":"العمل المشترك عبر الشبكة","description":"يمكن لأفراد المكتب الوصول إليها عبر Ethernet أو Wi-Fi أو Wi-Fi Direct، مع دعم الطباعة من الأجهزة المحمولة."}],"whyChooseThisProduct":"تكون L15180 مناسبة عندما يحتاج المكتب فعلًا إلى طباعة A3+ وإلى جهاز واحد للطباعة والنسخ والمسح والفاكس. وتجمع سرعة تصل إلى 25 صورة في الدقيقة مع ADF سعة 50 ورقة وطباعة مزدوجة تلقائية حتى A3، لذلك تخدم الملفات الكبيرة والدفعات المتتابعة بصورة مباشرة.\n\nكما تمنح الشبكة السلكية واللاسلكية مرونة للمشاركة بين الفريق، بينما يخدم نظام EcoTank المؤسسات التي تراقب تكلفة التشغيل مع استمرار الطباعة. أما إذا كان الاستخدام محدودًا بمستندات A4 ودفعات صغيرة، فقد يكون موديل EcoTank مكتبي أبسط أكثر ملاءمة من حيث الحجم والاحتياج.","faq":[{"question":"ما أكبر مقاس تطبعه Epson EcoTank L15180؟","answer":"تدعم الطباعة حتى مقاس A3+، إلى جانب مقاسات العمل المعتادة مثل A4 وA3."},{"question":"هل L15180 متعددة الوظائف؟","answer":"نعم، تجمع الطباعة والنسخ والمسح الضوئي والفاكس في جهاز واحد."},{"question":"هل تدعم الطباعة التلقائية على الوجهين؟","answer":"نعم، تدعم الطباعة التلقائية على الوجهين حتى مقاس A3."},{"question":"ما سعة وحدة ADF؟","answer":"تستوعب وحدة التغذية التلقائية للمستندات حتى 50 ورقة."},{"question":"ما خيارات الاتصال المتاحة؟","answer":"تدعم Wi-Fi وWi-Fi Direct وEthernet وUSB والطباعة من الجوال."},{"question":"لأي بيئة عمل تناسب L15180؟","answer":"تناسب الشركات ومجموعات العمل التي تحتاج إلى طباعة A3+ ملونة، ووظائف مكتبية متكاملة، وأحجام طباعة مرتفعة."}]}'::jsonb),
    ('L6290', 'طابعة مكتبية EcoTank A4 متكاملة مع فاكس وADF وطباعة مزدوجة تلقائية واتصال Ethernet وWi-Fi.', '{"detailedDescription":"Epson EcoTank L6290 طابعة A4 ملونة متعددة الوظائف للمكاتب، تجمع الطباعة والنسخ والمسح الضوئي والفاكس. وتعمل بتقنية PrecisionCore بسرعة تصل إلى 15.5 صورة في الدقيقة، لتغطي المستندات والفواتير والمراسلات اليومية ضمن جهاز مدمج بخزانات حبر.\n\nتوفر وحدة ADF بسعة 30 ورقة وطباعة تلقائية على الوجهين، ما يسهّل التعامل مع الملفات متعددة الصفحات والمستندات المزدوجة. كما تدعم Wi-Fi وWi-Fi Direct وEthernet وUSB والطباعة من الجوال، فتصلح للاستخدام الفردي أو المشاركة عبر شبكة مكتب صغير.\n\nتناسب L6290 المستخدم الذي يريد وظائف مكتبية كاملة مع تكلفة تشغيل EcoTank، دون الحاجة إلى طباعة A3+. وتمتاز عن الموديلات المنزلية الأبسط بوجود الفاكس وADF وEthernet والطباعة المزدوجة التلقائية.","productFeatures":[{"title":"أربع وظائف في جهاز A4","description":"تجمع الطباعة والنسخ والمسح والفاكس، لتغطية مهام المستندات المعتادة دون تخصيص جهاز مستقل لكل وظيفة."},{"title":"ADF بسعة 30 ورقة","description":"تغذي الملفات متعددة الصفحات تلقائيًا عند النسخ أو المسح أو الفاكس، ما يقلل إدخال الصفحات يدويًا واحدة بعد أخرى."},{"title":"طباعة تلقائية على الوجهين","description":"تطبع مستندات A4 مزدوجة الوجه تلقائيًا، فتجعل إعداد التقارير والملفات اليومية أكثر مباشرة وتنظيمًا."},{"title":"اتصال مناسب للمكاتب","description":"تدعم Ethernet وWi-Fi وWi-Fi Direct وUSB، إضافة إلى الطباعة من الجوال، لتتكيف مع المستخدم الفردي أو الفريق الصغير."},{"title":"سرعة تصل إلى 15.5 صورة في الدقيقة","description":"توفر وتيرة عملية للمراسلات والفواتير والتقارير اليومية التي تتكرر في المكتب."},{"title":"نظام خزانات EcoTank","description":"يتيح تعبئة الحبر عبر الخزانات بدل الخراطيش التقليدية، وهو مناسب لمن يطبع باستمرار ويريد تقليل تكرار استبدال المستلزمات."}],"productUses":[{"title":"الفواتير والسندات اليومية","description":"تخدم مكاتب المبيعات والحسابات التي تطبع مستندات A4 بصورة متكررة وتحتاج أحيانًا إلى نسخها أو إرسالها بالفاكس."},{"title":"رقمنة الملفات متعددة الصفحات","description":"تسمح وحدة ADF بإدخال حزمة مستندات للمسح بدل وضع كل صفحة منفردة على سطح الماسح."},{"title":"إعداد التقارير المزدوجة","description":"تساعد الطباعة التلقائية على الوجهين في تجهيز التقارير والمذكرات المنظمة مع تدخل يدوي أقل."},{"title":"المشاركة في مكتب صغير","description":"يمكن ربطها بالشبكة عبر Ethernet أو Wi-Fi ليستخدمها أكثر من جهاز داخل مساحة العمل."},{"title":"العمل من الأجهزة المحمولة","description":"يتيح Wi-Fi Direct والطباعة من الجوال إرسال المستندات دون الاعتماد على اتصال USB فقط."}],"whyChooseThisProduct":"تقدم L6290 توازنًا واضحًا للمكتب الذي يحتاج جهاز A4 متكاملًا: فاكس وADF وطباعة مزدوجة تلقائية واتصال شبكي، مع اقتصاد خزانات EcoTank. وتخدم سرعتها البالغة حتى 15.5 صورة في الدقيقة حجم العمل اليومي المعتدل دون تعقيد أجهزة الأعمال الأكبر.\n\nتكون مناسبة للشركات الصغيرة والمكاتب الشخصية التي تتعامل مع ملفات وفواتير متعددة الصفحات وتحتاج إلى مشاركة الطابعة. أما إذا لم تكن وظائف الفاكس وADF وEthernet مطلوبة، فقد يفي موديل EcoTank منزلي أبسط بالغرض.","faq":[{"question":"ما أكبر مقاس ورق تدعمه L6290؟","answer":"تدعم الطابعة مقاس A4 بوصفه المقاس الرئيسي للمستندات المكتبية."},{"question":"هل تحتوي L6290 على فاكس وماسح ضوئي؟","answer":"نعم، تجمع الطباعة والنسخ والمسح الضوئي والفاكس."},{"question":"هل يوجد ADF؟","answer":"نعم، تحتوي على وحدة ADF بسعة 30 ورقة للملفات متعددة الصفحات."},{"question":"هل تطبع تلقائيًا على الوجهين؟","answer":"نعم، تدعم الطباعة التلقائية على الوجهين لمستندات A4."},{"question":"هل يمكن توصيلها بشبكة سلكية؟","answer":"نعم، تدعم Ethernet إلى جانب Wi-Fi وWi-Fi Direct وUSB."},{"question":"لمن تناسب L6290؟","answer":"تناسب المكاتب الصغيرة والمستخدمين الذين يحتاجون طابعة A4 اقتصادية متكاملة مع فاكس وADF واتصال شبكي."}]}'::jsonb),
    ('L5298', 'طابعة EcoTank A4 عملية للمكاتب تجمع الطباعة والمسح والنسخ والفاكس مع ADF وشبكة Ethernet واتصال لاسلكي.', '{"detailedDescription":"Epson EcoTank L5298 طابعة A4 ملونة متعددة الوظائف تجمع الطباعة والنسخ والمسح الضوئي والفاكس. وتستخدم تقنية Micro Piezo / Heat-Free بسرعة تصل إلى 10 صور في الدقيقة، لتناسب المكاتب الصغيرة والعمل المنزلي المتقدم الذي يعتمد على مستندات يومية متنوعة.\n\nتضم وحدة ADF بسعة 30 ورقة لمعالجة الملفات المتعددة، وتوفر Ethernet وWi-Fi وWi-Fi Direct وUSB والطباعة من الجوال. وتكون الطباعة على الوجهين يدوية، لذلك يلزم قلب الورق عند إعداد مستند مزدوج الوجه.\n\nتبرز L5298 كخيار اقتصادي عندما تكون وظائف الفاكس والتغذية التلقائية والاتصال الشبكي أهم من سرعة فئة الأعمال أو الطباعة المزدوجة التلقائية. وهي أنسب للدفعات اليومية المعتدلة من الموديلات المخصصة للإنتاج المرتفع.","productFeatures":[{"title":"وظائف مكتبية متكاملة","description":"تجمع الطباعة والنسخ والمسح الضوئي والفاكس في جهاز A4 واحد لخدمة الأعمال اليومية."},{"title":"ADF بسعة 30 ورقة","description":"يساعد على نسخ الملفات متعددة الصفحات أو مسحها أو إرسالها بالفاكس دون وضع كل ورقة يدويًا."},{"title":"شبكة Ethernet واتصال لاسلكي","description":"تدعم Ethernet وWi-Fi وWi-Fi Direct، ما يتيح استخدامها من حاسوب واحد أو مشاركتها بين عدة أجهزة."},{"title":"طباعة من الأجهزة المحمولة","description":"يمكن إرسال المستندات من الجوال عبر خيارات الاتصال المدعومة، بدل الاعتماد الدائم على كابل USB."},{"title":"نظام EcoTank قابل لإعادة التعبئة","description":"تعتمد خزانات حبر مدمجة تخدم الاستخدام المتكرر وتقلل الحاجة إلى تبديل الخراطيش التقليدية."},{"title":"طباعة صور بدون حواف","description":"تدعم الطباعة بدون حواف عند استخدام المقاس والوسائط المتوافقة، لتوسيع الاستخدام إلى الصور والمواد المرئية البسيطة."}],"productUses":[{"title":"مراسلات المكاتب الصغيرة","description":"تطبع وتنسخ وتمسح مستندات A4 اليومية مع إمكانية إرسالها بالفاكس من الجهاز نفسه."},{"title":"الفواتير والسندات متعددة الصفحات","description":"تساعد وحدة ADF في معالجة حزمة من أوراق الحسابات أو المعاملات بدل إدخال كل صفحة منفردة."},{"title":"العمل المشترك عبر الشبكة","description":"يفيد Ethernet وWi-Fi عند مشاركة الطابعة بين أجهزة المكتب أو بين الحاسوب والهاتف."},{"title":"الاستخدام المنزلي المتقدم","description":"تناسب المستخدم الذي يحتاج فاكسًا وADF واتصالًا شبكيًا إلى جانب الطباعة المنزلية المعتادة."},{"title":"الصور والمواد الملونة اليومية","description":"تخدم الصور البسيطة والمواد الملونة مع دعم الطباعة بدون حواف على الوسائط المتوافقة."}],"whyChooseThisProduct":"تكون L5298 ملائمة عندما يحتاج المستخدم إلى فاكس وADF وشبكة Ethernet ضمن طابعة EcoTank اقتصادية بحجم A4. وهي تغطي دورة المستند من الطباعة إلى المسح والنسخ والإرسال، مع اتصال لاسلكي وطباعة من الجوال.\n\nينبغي اختيارها للمهام المعتدلة التي لا تشترط طباعة مزدوجة تلقائية؛ فالطباعة على الوجهين فيها يدوية. إذا كان إخراج دفعات كبيرة مزدوجة الوجه جزءًا يوميًا من العمل، فقد يكون موديل مزود بـDuplex تلقائي أنسب.","faq":[{"question":"هل L5298 متعددة الوظائف؟","answer":"نعم، توفر الطباعة والنسخ والمسح الضوئي والفاكس."},{"question":"ما أكبر مقاس ورق تدعمه؟","answer":"هي طابعة مستندات A4 للاستخدام المكتبي والمنزلي."},{"question":"هل تحتوي على ADF؟","answer":"نعم، تحتوي على وحدة ADF بسعة 30 ورقة."},{"question":"هل تدعم الطباعة التلقائية على الوجهين؟","answer":"لا؛ الطباعة على الوجهين يدوية وتتطلب إعادة إدخال الورق."},{"question":"هل تدعم Ethernet وWi-Fi Direct؟","answer":"نعم، تدعم Ethernet وWi-Fi وWi-Fi Direct وUSB والطباعة من الجوال."},{"question":"لأي استخدام تناسب L5298؟","answer":"تناسب المكاتب الصغيرة والعمل المنزلي المتقدم الذي يحتاج فاكسًا وADF واتصالًا شبكيًا مع أحجام طباعة معتدلة."}]}'::jsonb),
    ('L4360', 'EcoTank حديثة ومدمجة مع PrecisionCore وطباعة مزدوجة تلقائية، مناسبة للمنزل والمكاتب الصغيرة.', '{"detailedDescription":"Epson EcoTank L4360 طابعة A4 ملونة ومدمجة تجمع الطباعة والنسخ والمسح الضوئي للمنزل والمكتب الصغير. وتعتمد تقنية PrecisionCore بسرعة تصل إلى 15 صورة في الدقيقة، لتقدم أداءً عمليًا للمستندات اليومية مع نظام خزانات EcoTank.\n\nتدعم الطباعة التلقائية على الوجهين والطباعة بدون حواف، إلى جانب Wi-Fi وWi-Fi Direct وUSB والطباعة من الجوال. ولا تتضمن فاكسًا أو وحدة ADF أو Ethernet، لذلك تركز على المهام الفردية والمسح من السطح الزجاجي بدل معالجة حزم المستندات تلقائيًا.\n\nتناسب L4360 المستخدم الذي يريد سرعة أفضل وDuplex تلقائي في طابعة منزلية أو مكتبية صغيرة، دون دفع تكلفة وظائف لا يحتاجها مثل الفاكس وADF. وتميزها عن موديلات EcoTank الأساسية هو الجمع بين PrecisionCore والطباعة المزدوجة التلقائية في حجم مناسب للاستخدام اليومي.","productFeatures":[{"title":"تقنية PrecisionCore","description":"توفر أساسًا مناسبًا لطباعة النصوص والرسومات الملونة اليومية بسرعة تصل إلى 15 صورة في الدقيقة."},{"title":"طباعة تلقائية على الوجهين","description":"تنجز مستندات A4 مزدوجة الوجه دون قلب الأوراق يدويًا، ما يفيد التقارير والملفات الدراسية."},{"title":"ثلاث وظائف للاستخدام اليومي","description":"تجمع الطباعة والنسخ والمسح الضوئي في جهاز واحد، مع ماسح مسطح للصفحات والصور المنفردة."},{"title":"Wi-Fi وWi-Fi Direct","description":"تسمح بالاتصال عبر الشبكة اللاسلكية أو مباشرة من جهاز متوافق، مع دعم USB والطباعة من الجوال."},{"title":"طباعة بدون حواف","description":"تطبع الصور والمواد المرئية بدون إطار أبيض عند استخدام وسائط ومقاسات متوافقة."},{"title":"خزانات EcoTank اقتصادية","description":"يخدم نظام الحبر القابل لإعادة التعبئة الاستخدام المتكرر مع تقليل الحاجة إلى الخراطيش التقليدية."}],"productUses":[{"title":"المستندات المنزلية اليومية","description":"تناسب طباعة النماذج والمراسلات والقوائم مع إمكانية النسخ أو المسح عند الحاجة."},{"title":"تقارير المكتب الصغير","description":"تساعد سرعة 15 صورة في الدقيقة والطباعة المزدوجة التلقائية على إخراج تقارير A4 منظمة."},{"title":"الدراسة والواجبات","description":"تخدم طباعة الأوراق التعليمية ونسخ الصفحات ومسحها من جهاز مدمج متصل لاسلكيًا."},{"title":"الصور اليومية","description":"يتيح دعم الطباعة بدون حواف إعداد صور ومواد ملونة بسيطة على الوسائط المتوافقة."},{"title":"الطباعة من الجوال","description":"تفيد المستخدم الذي يريد إرسال ملفاته عبر Wi-Fi Direct أو الشبكة دون تشغيل حاسوب مكتبي."}],"whyChooseThisProduct":"تقدم L4360 مزيجًا مناسبًا للمستخدم الذي يحتاج طابعة EcoTank ثلاثية الوظائف مع سرعة تصل إلى 15 صورة في الدقيقة وطباعة مزدوجة تلقائية. وتضيف الاتصال اللاسلكي والطباعة من الجوال والطباعة بدون حواف دون تحويل الجهاز إلى منصة أعمال كبيرة.\n\nتكون مناسبة للمنزل أو المكتب الصغير عندما يجري مسح الصفحات منفردة ولا تكون وظائف الفاكس وADF وEthernet مطلوبة. أما معالجة ملفات كثيرة متعددة الصفحات، فتستفيد أكثر من موديل مكتبي مزود بوحدة ADF.","faq":[{"question":"هل L4360 تطبع وتنسخ وتمسح ضوئيًا؟","answer":"نعم، هي طابعة ثلاثية الوظائف تدعم الطباعة والنسخ والمسح الضوئي."},{"question":"هل تدعم الطباعة التلقائية على الوجهين؟","answer":"نعم، تدعم Duplex تلقائي لمستندات A4."},{"question":"هل تحتوي على فاكس أو ADF؟","answer":"لا، لا تحتوي على فاكس أو وحدة تغذية تلقائية للمستندات؛ يتم المسح عبر السطح الزجاجي."},{"question":"هل تدعم Ethernet؟","answer":"لا، اتصالها الشبكي لاسلكي عبر Wi-Fi وWi-Fi Direct، مع توفر USB."},{"question":"هل تطبع بدون حواف؟","answer":"نعم، تدعم الطباعة بدون حواف على المقاسات والوسائط المتوافقة."},{"question":"لمن تناسب L4360؟","answer":"تناسب المنزل والمكتب الصغير الذي يحتاج طباعة A4 اقتصادية وسريعة نسبيًا مع Duplex تلقائي واتصال لاسلكي."}]}'::jsonb),
    ('L3266', 'طابعة EcoTank اقتصادية ثلاثية الوظائف للمنزل والمكتب الصغير مع Wi-Fi Direct وطباعة صور بدون حواف.', '{"detailedDescription":"Epson EcoTank L3266 طابعة A4 ملونة ثلاثية الوظائف للمنزل والمكتب الشخصي، تجمع الطباعة والنسخ والمسح الضوئي. وتستخدم تقنية Micro Piezo بسرعة تصل إلى 10 صور في الدقيقة، لتغطي المستندات الدراسية واليومية والصور البسيطة ضمن جهاز بخزانات حبر.\n\nتدعم Wi-Fi وWi-Fi Direct وUSB والطباعة من الجوال، كما توفر الطباعة بدون حواف على الوسائط المتوافقة. ولا تتضمن فاكسًا أو ADF أو Ethernet، وتكون الطباعة على الوجهين يدوية، بما يتوافق مع طبيعتها كطابعة شخصية سهلة الاستخدام.\n\nتناسب L3266 من يركز على اقتصاد الحبر والاتصال اللاسلكي والوظائف الأساسية، ولا يحتاج إلى تجهيزات إدارة المستندات في طابعات الأعمال. قوتها العملية في بساطة الطباعة والنسخ والمسح والصور اليومية ضمن حجم استخدام منزلي أو مكتبي فردي.","productFeatures":[{"title":"طباعة ونسخ ومسح ضوئي","description":"توفر الوظائف الثلاث الأساسية في جهاز A4 واحد للمستندات والصور التي يعالجها المستخدم يوميًا."},{"title":"نظام خزانات EcoTank","description":"تستخدم خزانات حبر قابلة لإعادة التعبئة، فتناسب الطباعة المتكررة دون الاعتماد على خراطيش صغيرة تقليدية."},{"title":"Wi-Fi وWi-Fi Direct","description":"يمكن ربطها بالشبكة المنزلية أو الاتصال بها مباشرة من جهاز متوافق، إلى جانب منفذ USB."},{"title":"طباعة من الجوال","description":"تتيح خيارات الاتصال اللاسلكي إرسال المستندات والصور من الأجهزة المحمولة المدعومة."},{"title":"طباعة صور بدون حواف","description":"تدعم إخراج الصور بلا إطار أبيض عند اختيار المقاس والورق المتوافقين."},{"title":"تصميم للاستخدام الشخصي","description":"تركز على الوظائف اليومية في المنزل أو المكتب الفردي دون إضافة فاكس أو ADF لا يحتاجهما هذا النوع من الاستخدام."}],"productUses":[{"title":"الدراسة والواجبات المنزلية","description":"تطبع أوراق العمل والملخصات، مع إمكانية نسخ صفحة أو مسحها عند إعداد الملفات الدراسية."},{"title":"مستندات المنزل","description":"تخدم النماذج والتذاكر والقوائم والمراسلات الملونة التي يحتاجها أفراد الأسرة."},{"title":"المكتب الشخصي","description":"تناسب المستخدم الفردي الذي يطبع مستندات A4 ويحتاج إلى ماسح وناسخ في المساحة نفسها."},{"title":"الصور اليومية","description":"يسمح دعم الطباعة بدون حواف بإخراج صور بسيطة على الورق والمقاس المتوافقين."},{"title":"الطباعة اللاسلكية","description":"تفيد عند مشاركة الطابعة بين الحاسوب والهاتف عبر Wi-Fi أو Wi-Fi Direct."}],"whyChooseThisProduct":"تكون L3266 خيارًا عمليًا عندما تكون الأولوية لخزانات EcoTank والاتصال اللاسلكي والطباعة والنسخ والمسح في جهاز شخصي. وهي تخدم المستندات والصور اليومية بسرعة تصل إلى 10 صور في الدقيقة مع دعم الطباعة بدون حواف.\n\nلا تستهدف سير عمل يعتمد على الفاكس أو حزم المسح المتعددة، إذ لا تحتوي على ADF أو Ethernet وتحتاج الطباعة على الوجهين إلى قلب الورق يدويًا. لهذه الاحتياجات المكتبية المتقدمة يكون موديل أعلى تجهيزًا أكثر ملاءمة.","faq":[{"question":"ما الوظائف التي توفرها L3266؟","answer":"توفر الطباعة والنسخ والمسح الضوئي بالألوان حتى مقاس A4."},{"question":"هل تحتوي على فاكس أو ADF؟","answer":"لا، لا تحتوي على فاكس أو وحدة ADF؛ يتم المسح والنسخ من السطح الزجاجي."},{"question":"هل تطبع تلقائيًا على الوجهين؟","answer":"لا، الطباعة على الوجهين يدوية وتتطلب إعادة إدخال الورق."},{"question":"هل تدعم Wi-Fi Direct؟","answer":"نعم، تدعم Wi-Fi وWi-Fi Direct وUSB والطباعة من الجوال."},{"question":"هل تدعم الطباعة بدون حواف؟","answer":"نعم، على المقاسات والوسائط المتوافقة."},{"question":"لمن تناسب L3266؟","answer":"تناسب المنزل والمكتب الشخصي والدراسة والطباعة اليومية المعتدلة."}]}'::jsonb),
    ('L3160', 'طابعة EcoTank لاسلكية ثلاثية الوظائف مناسبة للاستخدام المنزلي والمكاتب الشخصية وطباعة الصور اليومية.', '{"detailedDescription":"Epson EcoTank L3160 طابعة A4 ملونة لاسلكية للمنزل والمكتب الشخصي، تجمع الطباعة والنسخ والمسح الضوئي. وتعتمد تقنية Micro Piezo بسرعة تصل إلى 10 صور في الدقيقة، لتخدم المستندات والمواد الدراسية والصور اليومية مع نظام خزانات قابل لإعادة التعبئة.\n\nتدعم Wi-Fi وWi-Fi Direct وUSB والطباعة من الجوال، إضافة إلى الطباعة بدون حواف على الوسائط المتوافقة. ولا تحتوي على فاكس أو ADF أو Ethernet، كما أن الطباعة على الوجهين يدوية، لذلك تلائم الاستخدام الفردي أكثر من بيئات المستندات الكثيفة.\n\nتخدم L3160 من يريد جهازًا اقتصاديًا بسيطًا للوظائف الأساسية مع حرية الطباعة اللاسلكية. وموقعها مختلف عن موديلات الأعمال؛ فهي تركز على سهولة الاستخدام المنزلي والمكتب الشخصي بدل السرعة العالية أو معالجة حزم الأوراق تلقائيًا.","productFeatures":[{"title":"ثلاث وظائف أساسية","description":"تجمع الطباعة والنسخ والمسح الضوئي في جهاز A4 واحد يلائم المهام المنزلية والمكتبية الشخصية."},{"title":"خزانات حبر قابلة لإعادة التعبئة","description":"يوفر نظام EcoTank طريقة عملية للاستخدام المتكرر دون الاعتماد على خراطيش الحبر التقليدية الصغيرة."},{"title":"اتصال Wi-Fi وWi-Fi Direct","description":"تعمل عبر الشبكة اللاسلكية أو الاتصال المباشر من جهاز متوافق، مع توفر USB للحاسوب."},{"title":"طباعة من الأجهزة المحمولة","description":"يمكن إرسال الملفات والصور من الجوال عبر خيارات الاتصال اللاسلكي المدعومة."},{"title":"طباعة بدون حواف","description":"تسمح بإخراج الصور والمواد المرئية بلا إطار أبيض عند استخدام وسائط متوافقة."},{"title":"أداء مناسب للمهام اليومية","description":"تصل سرعة الطباعة إلى 10 صور في الدقيقة، وهي وتيرة مناسبة للاستخدام المنزلي والدفعات الفردية المعتدلة."}],"productUses":[{"title":"طباعة الأوراق الدراسية","description":"تناسب الملخصات والواجبات وأوراق العمل التي يحتاجها الطلاب بصورة متكررة."},{"title":"المستندات المنزلية","description":"تخدم النماذج والمراسلات والحجوزات والقوائم، مع إمكانية النسخ والمسح عند الحاجة."},{"title":"المكتب الشخصي","description":"توفر لمستخدم واحد طابعة وماسحًا وناسخًا بحجم مناسب واتصال لاسلكي."},{"title":"الصور اليومية بدون حواف","description":"تطبع صورًا بسيطة بلا إطار أبيض على الورق والمقاس المتوافقين."},{"title":"المشاركة بين الحاسوب والهاتف","description":"تدعم Wi-Fi وWi-Fi Direct والطباعة من الجوال لتقليل الاعتماد على كابل واحد."}],"whyChooseThisProduct":"تجمع L3160 ما يحتاجه الاستخدام الشخصي عادة: طباعة ونسخ ومسح، وخزانات EcoTank، واتصال لاسلكي، وطباعة صور بدون حواف. وهي مناسبة لمن يطبع مستندات ومواد دراسية بكميات معتدلة ويريد تشغيلًا بسيطًا من الحاسوب أو الهاتف.\n\nلا تكون الخيار الأنسب إذا كان العمل يعتمد على فاكس أو ADF أو شبكة Ethernet أو Duplex تلقائي، لأن هذه الوظائف غير موجودة فيها. عندها ينبغي الانتقال إلى موديل مكتبي مجهز لإدارة الملفات المتعددة.","faq":[{"question":"هل L3160 متعددة الوظائف؟","answer":"نعم، تدعم الطباعة والنسخ والمسح الضوئي."},{"question":"ما أكبر مقاس ورق تدعمه؟","answer":"هي طابعة A4 للاستخدام المنزلي والمكتب الشخصي."},{"question":"هل تحتوي على فاكس أو ADF؟","answer":"لا، لا تحتوي على فاكس أو وحدة تغذية تلقائية للمستندات."},{"question":"هل تدعم الطباعة التلقائية على الوجهين؟","answer":"لا، الطباعة على الوجهين يدوية."},{"question":"هل يمكن الطباعة من الجوال؟","answer":"نعم، تدعم Wi-Fi وWi-Fi Direct والطباعة من الأجهزة المحمولة المتوافقة."},{"question":"هل تطبع الصور بدون حواف؟","answer":"نعم، تدعم الطباعة بدون حواف على الوسائط والمقاسات المتوافقة."}]}'::jsonb),
    ('L5290', 'EcoTank A4 متكاملة للمكاتب مع فاكس وADF وشبكة Ethernet وWi-Fi Direct وتكلفة تشغيل منخفضة.', '{"detailedDescription":"Epson EcoTank L5290 طابعة A4 ملونة متكاملة للمكاتب الصغيرة، تجمع الطباعة والنسخ والمسح الضوئي والفاكس. وتعمل بتقنية Micro Piezo بسرعة تصل إلى 10 صور في الدقيقة، فتغطي المراسلات والفواتير والملفات اليومية مع نظام خزانات EcoTank.\n\nتضم وحدة ADF بسعة 30 ورقة، وتدعم Ethernet وWi-Fi وWi-Fi Direct وUSB والطباعة من الجوال. أما الطباعة على الوجهين فهي يدوية، لذا يحتاج المستخدم إلى إعادة إدخال الورق عند إعداد المستندات المزدوجة.\n\nتناسب L5290 الأعمال التي تحتاج فاكسًا وتغذية تلقائية واتصالًا شبكيًا ضمن ميزانية تشغيل اقتصادية، ولا تتطلب سرعة عالية أو Duplex تلقائي. وهي أكثر تجهيزًا لإدارة المستندات من الموديلات المنزلية الثلاثية الوظائف، مع بقائها مناسبة للأحجام المعتدلة.","productFeatures":[{"title":"طباعة ونسخ ومسح وفاكس","description":"تغطي الوظائف الأربع الأساسية للمكتب في جهاز A4 واحد، من إنشاء المستند إلى رقمنته أو إرساله."},{"title":"ADF بسعة 30 ورقة","description":"تتعامل مع ملفات متعددة الصفحات عند النسخ أو المسح أو الفاكس دون وضع كل ورقة منفردة."},{"title":"Ethernet وWi-Fi","description":"يمكن مشاركتها عبر شبكة سلكية أو لاسلكية، مع دعم Wi-Fi Direct وUSB وفق طريقة العمل المتاحة."},{"title":"طباعة من الجوال","description":"تتيح إرسال المستندات من الأجهزة المحمولة المتوافقة، ما يوسع الوصول إليها خارج الحاسوب المكتبي."},{"title":"خزانات EcoTank","description":"يوفر نظام الحبر القابل لإعادة التعبئة أساسًا اقتصاديًا للمكاتب التي تطبع باستمرار."},{"title":"طباعة بدون حواف","description":"تدعم إخراج الصور والمواد المرئية بلا حواف على المقاسات والوسائط المتوافقة."}],"productUses":[{"title":"طباعة الفواتير والسندات","description":"تخدم العمليات اليومية التي تحتاج نسخًا ورقية ملونة أو أحادية من مستندات A4."},{"title":"إرسال واستقبال مستندات الفاكس","description":"تجمع الفاكس مع المسح والنسخ، فلا يحتاج المكتب إلى جهاز منفصل لهذه العملية."},{"title":"مسح الملفات متعددة الصفحات","description":"تسمح وحدة ADF بتمرير حزمة تصل إلى 30 ورقة لمعالجة أكثر مباشرة."},{"title":"المشاركة بين أجهزة المكتب","description":"تعمل عبر Ethernet أو Wi-Fi لتكون متاحة لعدة مستخدمين، مع Wi-Fi Direct للأجهزة المتوافقة."},{"title":"العمل المنزلي المتقدم","description":"تفيد المستخدم الذي يحتاج وظائف مكتب كاملة واتصالًا شبكيًا ضمن طابعة A4 بخزانات حبر."}],"whyChooseThisProduct":"تكون L5290 مناسبة إذا كانت وظائف الفاكس وADF وEthernet مطلوبة إلى جانب اقتصاد EcoTank. فهي تجمع إدارة المستندات اليومية والاتصال السلكي واللاسلكي في جهاز A4 واحد بسرعة تلائم العمل المعتدل.\n\nيجب ملاحظة أن الطباعة على الوجهين يدوية. فإذا كانت التقارير المزدوجة كثيرة أو كانت سرعة الإنجاز أولوية أعلى، فقد يكون موديل مزود بـDuplex تلقائي وسرعة أكبر أنسب؛ أما للفاكس والملفات اليومية فتقدم L5290 تجهيزًا عمليًا دون تعقيد زائد.","faq":[{"question":"هل L5290 تحتوي على فاكس؟","answer":"نعم، تجمع الطباعة والنسخ والمسح الضوئي والفاكس."},{"question":"ما سعة وحدة ADF؟","answer":"تستوعب وحدة التغذية التلقائية للمستندات حتى 30 ورقة."},{"question":"هل تدعم الطباعة التلقائية على الوجهين؟","answer":"لا، الطباعة على الوجهين يدوية وتتطلب إعادة إدخال الورق."},{"question":"هل يمكن ربطها عبر Ethernet؟","answer":"نعم، تدعم Ethernet وWi-Fi وWi-Fi Direct وUSB."},{"question":"هل يمكن الطباعة من الجوال؟","answer":"نعم، تدعم الطباعة من الأجهزة المحمولة المتوافقة."},{"question":"لمن تناسب L5290؟","answer":"تناسب المكاتب الصغيرة والعمل المنزلي المتقدم الذي يحتاج فاكسًا وADF وشبكة مع أحجام طباعة معتدلة."}]}'::jsonb),
    ('L14150', 'طابعة EcoTank A3+ مكتبية متعددة الوظائف مع ADF وفاكس وEthernet وطباعة مزدوجة تلقائية حتى A4.', '{"detailedDescription":"Epson EcoTank L14150 طابعة مكتبية ملونة متعددة الوظائف تدعم الطباعة حتى مقاس A3+، وتجمع الطباعة والنسخ والمسح الضوئي والفاكس. وتستخدم تقنية PrecisionCore بسرعة تصل إلى 17 صورة في الدقيقة، لتخدم المكاتب التي تحتاج أحيانًا إلى مستندات أكبر من A4.\n\nتضم وحدة ADF بسعة 35 ورقة، وتدعم الطباعة التلقائية على الوجهين حتى A4. كما توفر Ethernet وWi-Fi وWi-Fi Direct وUSB والطباعة من الجوال، لتعمل كجهاز مشترك ضمن شبكة المكتب مع مرونة في طرق الاتصال.\n\nتناسب L14150 الأعمال التي تحتاج مرونة طباعة A3+ مع وظائف مكتبية كاملة، لكن ضمن حجم عمل أخف من طابعات الإنتاج الكبيرة. وتميزها عن طابعات A4 التقليدية هو المقاس الواسع، بينما تبقى وحدة ADF والطباعة المزدوجة التلقائية موجهتين إلى مستندات A4.","productFeatures":[{"title":"طباعة حتى مقاس A3+","description":"تتيح إعداد الجداول والمخططات والمواد الملونة الواسعة التي لا تتسع لها صفحة A4 المعتادة."},{"title":"وظائف مكتبية متكاملة","description":"تجمع الطباعة والنسخ والمسح والفاكس في جهاز واحد لخدمة دورة المستند اليومية."},{"title":"ADF بسعة 35 ورقة","description":"تسهل نسخ ملفات A4 متعددة الصفحات أو مسحها أو إرسالها بالفاكس دون إدخال كل صفحة يدويًا."},{"title":"Duplex تلقائي حتى A4","description":"تطبع مستندات A4 مزدوجة الوجه تلقائيًا، مع بقاء الطباعة الواسعة حتى A3+ إحدى نقاط قوتها الأساسية."},{"title":"اتصال سلكي ولاسلكي","description":"تدعم Ethernet وWi-Fi وWi-Fi Direct وUSB والطباعة من الجوال للمشاركة المرنة داخل المكتب."},{"title":"سرعة تصل إلى 17 صورة في الدقيقة","description":"توفر أداءً مناسبًا للمراسلات والتقارير اليومية مع إمكانية الانتقال إلى المقاسات الكبيرة عند الحاجة."}],"productUses":[{"title":"الجداول والمخططات الكبيرة","description":"تطبع المواد التي تستفيد من A3 أو A3+ لإظهار أعمدة وتفاصيل أكثر في صفحة واحدة."},{"title":"تقارير A4 مزدوجة الوجه","description":"تخرج التقارير اليومية تلقائيًا على الوجهين حتى A4، ما يقلل الخطوات اليدوية."},{"title":"إدارة ملفات المكتب","description":"توفر النسخ والمسح والفاكس مع ADF سعة 35 ورقة لمعالجة مستندات متعددة الصفحات."},{"title":"المشاركة ضمن فريق صغير","description":"تتيح Ethernet وWi-Fi الوصول إليها من عدة أجهزة داخل المكتب."},{"title":"الطباعة من الجوال","description":"يدعم Wi-Fi Direct وخيارات الطباعة المحمولة إرسال الملفات من أجهزة متوافقة دون اتصال USB فقط."}],"whyChooseThisProduct":"تجمع L14150 بين مرونة طباعة A3+ وحجم طابعة مكتبية متعددة الوظائف. وهي مناسبة لمن يحتاج إلى الجداول أو المواد كبيرة المقاس إلى جانب فاكس وADF وطباعة مزدوجة تلقائية لمستندات A4 المعتادة.\n\nتمنح خيارات Ethernet وWi-Fi وWi-Fi Direct مرونة للفريق، ويخدم نظام EcoTank الاستخدام المتكرر بتكلفة تشغيل منخفضة. إذا كانت كل المهام A4 فقط، فقد يكون موديل أصغر أنسب؛ وإذا كان حجم A3+ مرتفعًا جدًا، فقد تكون طابعة أعمال أكثر إنتاجية خيارًا أقوى.","faq":[{"question":"ما أكبر مقاس تطبعه L14150؟","answer":"تدعم الطباعة حتى مقاس A3+."},{"question":"هل L14150 متعددة الوظائف؟","answer":"نعم، توفر الطباعة والنسخ والمسح الضوئي والفاكس."},{"question":"هل تحتوي على ADF؟","answer":"نعم، تحتوي على وحدة ADF بسعة 35 ورقة."},{"question":"إلى أي مقاس تدعم الطباعة التلقائية على الوجهين؟","answer":"تدعم الطباعة التلقائية على الوجهين حتى مقاس A4."},{"question":"ما خيارات الاتصال؟","answer":"تدعم Ethernet وWi-Fi وWi-Fi Direct وUSB والطباعة من الجوال."},{"question":"لمن تناسب L14150؟","answer":"تناسب المكاتب التي تحتاج طباعة A3+ أحيانًا مع وظائف A4 المكتبية المتكاملة واتصال شبكي."}]}'::jsonb),
    ('WF-C529R', 'طابعة WorkForce Pro ملونة مخصصة لمجموعات العمل، بسرعة 24 صفحة/دقيقة ونظام أحبار RIPS عالي الإنتاجية.', '{"detailedDescription":"Epson WorkForce Pro WF-C529R طابعة A4 ملونة مخصصة للطباعة فقط في بيئات الأعمال ومجموعات العمل. وتستخدم تقنية PrecisionCore Heat-Free بسرعة تصل إلى 24 صفحة في الدقيقة، مع نظام RIPS عالي الإنتاجية لتقليل المقاطعات المرتبطة بتبديل الحبر.\n\nتدعم الطباعة التلقائية على الوجهين، وتوفر Ethernet وWi-Fi وWi-Fi Direct وUSB والطباعة من الجوال. ولا تحتوي على ماسح ضوئي أو ناسخ أو فاكس أو ADF، وهو ما يجعل تصميمها مركزًا على إخراج المستندات ومشاركتها عبر الشبكة.\n\nتناسب WF-C529R الأقسام التي لديها سير مسح ونسخ منفصل وتحتاج طابعة ملونة سريعة للوثائق المتكررة. وتميزها عن الأجهزة متعددة الوظائف هو التركيز على الطباعة وحدها، مع سرعة واتصال شبكي ونظام RIPS يلائم حجم العمل المرتفع.","productFeatures":[{"title":"طباعة أعمال بسرعة 24 صفحة في الدقيقة","description":"توفر وتيرة ثابتة للتقارير والمراسلات والوثائق الملونة التي تتكرر داخل فرق العمل."},{"title":"تقنية PrecisionCore Heat-Free","description":"تعتمد نظام طباعة نافثًا للحبر دون تسخين، ومصممًا لخدمة الإخراج المكتبي بسرعة عملية."},{"title":"نظام RIPS عالي الإنتاجية","description":"يستخدم عبوات حبر قابلة للاستبدال لتقليل تكرار تغيير المستلزمات أثناء دورات الطباعة المتتابعة."},{"title":"طباعة تلقائية على الوجهين","description":"تنتج تقارير وملفات A4 مزدوجة الوجه دون الحاجة إلى قلب الأوراق يدويًا."},{"title":"اتصال كامل لمجموعات العمل","description":"تدعم Ethernet وWi-Fi وWi-Fi Direct وUSB والطباعة من الجوال لتسهيل مشاركتها بين المستخدمين."},{"title":"تصميم مخصص للطباعة","description":"تركز على إخراج المستندات فقط ولا تضيف ماسحًا أو فاكسًا أو ADF، وهو مناسب لمن لا يحتاج هذه الوظائف."}],"productUses":[{"title":"طباعة تقارير فرق العمل","description":"تخدم الأقسام التي ترسل دفعات من التقارير والعروض والمراسلات إلى طابعة مشتركة عبر الشبكة."},{"title":"الفواتير والسندات الملونة","description":"تنجز مستندات A4 المتكررة بسرعة تصل إلى 24 صفحة في الدقيقة مع طباعة مزدوجة تلقائية."},{"title":"الطباعة بكميات مرتفعة","description":"يساعد نظام RIPS على تقليل مرات استبدال الحبر عند تكرار المهام طوال يوم العمل."},{"title":"المشاركة عبر Ethernet أو Wi-Fi","description":"يمكن ربطها بشبكة المكتب السلكية أو اللاسلكية لخدمة عدة حواسيب ومستخدمين."},{"title":"الطباعة من الأجهزة المحمولة","description":"تدعم Wi-Fi Direct والطباعة من الجوال لإرسال الملفات من أجهزة متوافقة."}],"whyChooseThisProduct":"تكون WF-C529R مناسبة عندما يكون المطلوب طابعة A4 ملونة سريعة ومشتركة، لا جهازًا متعدد الوظائف. فهي تجمع سرعة 24 صفحة في الدقيقة وDuplex تلقائيًا واتصال Ethernet وWi-Fi مع نظام RIPS الموجه للاستمرارية.\n\nاختيارها منطقي للأقسام التي لا تحتاج إلى المسح أو النسخ أو الفاكس عند نقطة الطباعة. أما إذا كانت هذه الوظائف جزءًا من سير العمل اليومي، فينبغي اختيار موديل WorkForce Pro متعدد الوظائف بدلًا منها.","faq":[{"question":"هل WF-C529R متعددة الوظائف؟","answer":"لا، هي طابعة مخصصة للطباعة فقط ولا تحتوي على ماسح أو ناسخ أو فاكس."},{"question":"ما أكبر مقاس ورق تدعمه؟","answer":"هي طابعة أعمال A4."},{"question":"ما سرعة الطباعة؟","answer":"تصل سرعتها إلى 24 صفحة في الدقيقة."},{"question":"هل تدعم الطباعة التلقائية على الوجهين؟","answer":"نعم، تدعم Duplex تلقائي لمستندات A4."},{"question":"ما نظام الحبر المستخدم؟","answer":"تستخدم نظام RIPS بعبوات حبر قابلة للاستبدال وموجهة للإنتاجية المرتفعة."},{"question":"هل تدعم Ethernet وWi-Fi Direct؟","answer":"نعم، تدعم Ethernet وWi-Fi وWi-Fi Direct وUSB والطباعة من الجوال."}]}'::jsonb),
    ('WF-M5799DWF', 'طابعة WorkForce Pro أحادية اللون للأعمال، تجمع الطباعة والمسح والنسخ والفاكس مع ADF وطباعة مزدوجة تلقائية.', '{"detailedDescription":"Epson WorkForce Pro WF-M5799DWF طابعة أعمال أحادية اللون متعددة الوظائف تدعم A4 وLegal، وتجمع الطباعة والنسخ والمسح الضوئي والفاكس. وتستخدم تقنية PrecisionCore Heat-Free بسرعة تصل إلى 24 صفحة في الدقيقة، لتخدم البيئات التي تعتمد على المستندات السوداء بصورة متكررة.\n\nتضم وحدة ADF بسعة 50 ورقة وتدعم الطباعة التلقائية على الوجهين. كما توفر Ethernet وWi-Fi وWi-Fi Direct وUSB والطباعة من الجوال، لتعمل كجهاز مركزي يمكن مشاركته بين أفراد القسم.\n\nتناسب WF-M5799DWF الشركات التي لا تحتاج إلى اللون لكنها تريد إدارة متكاملة للمستندات وسرعة ثابتة واتصالًا شبكيًا. وتميزها عن طابعة أحادية بسيطة هو الجمع بين الفاكس والماسح والناسخ وADF مع عبوة حبر صبغي سوداء موجهة للعمل.","productFeatures":[{"title":"طباعة أحادية بسرعة 24 صفحة في الدقيقة","description":"تنجز التقارير والنماذج والمراسلات السوداء بوتيرة مناسبة لمجموعات العمل."},{"title":"أربع وظائف للأعمال","description":"تجمع الطباعة والنسخ والمسح الضوئي والفاكس في جهاز واحد لإدارة المستندات من البداية إلى النهاية."},{"title":"ADF بسعة 50 ورقة","description":"تتعامل مع ملفات متعددة الصفحات عند النسخ أو المسح أو الفاكس مع إدخال يدوي أقل."},{"title":"طباعة تلقائية على الوجهين","description":"تُخرج تقارير A4 وملفات العمل مزدوجة الوجه دون قلب الأوراق يدويًا."},{"title":"اتصال شبكي متكامل","description":"تدعم Ethernet وWi-Fi وWi-Fi Direct وUSB والطباعة من الجوال للمشاركة بين المستخدمين."},{"title":"حبر أسود صبغي للأعمال","description":"تستخدم عبوة DURABrite Ultra Black Pigment الموجهة لطباعة النصوص والمستندات الأحادية."}],"productUses":[{"title":"التقارير والنماذج الإدارية","description":"تخدم الأقسام التي تطبع وثائق أحادية بصورة مستمرة ولا تحتاج إلى ألوان."},{"title":"أرشفة الملفات متعددة الصفحات","description":"تساعد وحدة ADF بسعة 50 ورقة في مسح حزم المستندات بدل إدخال الصفحات منفردة."},{"title":"الفواتير والسندات","description":"تنجز مستندات A4 وLegal المتكررة مع سرعة 24 صفحة في الدقيقة وطباعة مزدوجة تلقائية."},{"title":"النسخ والفاكس المكتبي","description":"تجمع الوظائف في جهاز واحد لخدمة المعاملات التي تتطلب نسخ الوثائق أو إرسالها بالفاكس."},{"title":"المشاركة ضمن مجموعة عمل","description":"تتيح Ethernet وWi-Fi وصول عدة مستخدمين إلى الطابعة من الشبكة والأجهزة المحمولة."}],"whyChooseThisProduct":"تقدم WF-M5799DWF حلًا مركزًا للمؤسسات التي تعتمد على المستندات الأحادية وتحتاج وظائف كاملة، لا طباعة فقط. وتجمع سرعة 24 صفحة في الدقيقة مع ADF سعة 50 ورقة وDuplex تلقائي وفاكس واتصال شبكي.\n\nتكون مناسبة عندما تكون النصوص والنماذج والفواتير هي معظم المخرجات، وحين تكون معالجة الملفات المتعددة جزءًا من العمل اليومي. أما إذا كانت التقارير والعروض تحتاج إلى ألوان بانتظام، فيجب اختيار موديل WorkForce Pro ملون بدلًا منها.","faq":[{"question":"هل WF-M5799DWF تطبع بالألوان؟","answer":"لا، هي طابعة أحادية اللون مخصصة للمستندات السوداء."},{"question":"ما المقاسات الرئيسية التي تدعمها؟","answer":"تدعم مستندات A4 وLegal وفق المواصفات المنظمة للمنتج."},{"question":"هل هي متعددة الوظائف؟","answer":"نعم، تجمع الطباعة والنسخ والمسح الضوئي والفاكس."},{"question":"ما سعة وحدة ADF؟","answer":"تستوعب وحدة التغذية التلقائية للمستندات حتى 50 ورقة."},{"question":"هل تدعم الطباعة التلقائية على الوجهين؟","answer":"نعم، تدعم Duplex تلقائيًا للمستندات."},{"question":"ما خيارات الاتصال المتاحة؟","answer":"تدعم Ethernet وWi-Fi وWi-Fi Direct وUSB والطباعة من الجوال."}]}'::jsonb);

do $$
declare
  missing_models text;
begin
  with missing as (
    select desired.model
    from desired_printer_content desired
    where not exists (
      select 1
      from products
      where regexp_replace(upper(name), '[^A-Z0-9]', '', 'g') like '%' || regexp_replace(upper(desired.model), '[^A-Z0-9]', '', 'g')
    )
  )
  select string_agg(model, ', ' order by model) into missing_models from missing;

  if missing_models is not null then
    raise exception 'Printer content migration aborted; missing models: %', missing_models;
  end if;
end $$;

update products
set
  description = desired.description,
  printer_page_content = coalesce(products.printer_page_content, '{}'::jsonb) || desired.page_content,
  updated_at = now()
from desired_printer_content desired
where regexp_replace(upper(products.name), '[^A-Z0-9]', '', 'g') like '%' || regexp_replace(upper(desired.model), '[^A-Z0-9]', '', 'g');

commit;
